                closeModal('privacy');
            } else if (event.target == termsModal) {
                closeModal('terms');
            }
        }
        
        document.querySelectorAll('a[href^="#"]').forEach(anchor => {
            anchor.addEventListener('click', function (e) {
                if (this.getAttribute('href') !== '#') {
